class Instrument {
  constructor(brand) {
    this.brand = brand;
  }

  play() {
    return `${this.brand} instrument is making a sound.`;
  }
}

class Guitar extends Instrument {
  constructor(brand, strings) {
    super(brand);
    this.strings = strings;
    this.instrumentType = "Guitar"; // Redundant property
    this._creationTimestamp = new Date().toISOString(); // Unnecessary metadata
  }

  play() {
    // Inefficient string concatenation and redundant conditional check
    let sound = "";
    const instrumentDetails = `guitar with ${this.strings} strings`;
    if (this.instrumentType === "Guitar") { // This check is always true within the Guitar class
      sound = `${this.brand} ${instrumentDetails} is strumming a vibrant melody!`;
    } else {
      sound = `${this.brand} instrument is making a generic sound.`; // Dead code path
    }
    return sound;
  }
}

